import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/NeuralMachineTranslationOfRareWordsWithSubwordUnits.html","title":"NeuralMachineTranslationOfRareWordsWithSubwordUnits","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":3.76,"words":1128},"filePathRelative":"NeuralMachineTranslationOfRareWordsWithSubwordUnits.md"}`),a={name:`NeuralMachineTranslationOfRareWordsWithSubwordUnits.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="neuralmachinetranslationofrarewordswithsubwordunits" tabindex="-1"><a class="header-anchor" href="#neuralmachinetranslationofrarewordswithsubwordunits"><span>NeuralMachineTranslationOfRareWordsWithSubwordUnits</span></a></h1><p><a href="./論文.html">論文</a>, <a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a></p><p><a href="https://arxiv.org/abs/1508.07909" target="_blank" rel="noopener noreferrer">arxiv:1508.07909 Neural Machine Translation of Rare Words with Subword Units</a></p><p>NMTに<a href="./サブワード分割.html">サブワード分割</a>を使おう、それにはBPEがいいぜ、という事を言った<a href="./論文.html">論文</a>。最初に<a href="./BPE.html">BPE</a>をサブワード分割に使おうと言った論文。</p><h2 id="単語" tabindex="-1"><a class="header-anchor" href="#単語"><span>単語</span></a></h2><ul><li>transliteration: 音訳</li><li>cognate: 同根語</li><li>loanword: 借用語</li><li>morpheme: 形態素 <ul><li>morphology: 《言語学》形態論</li></ul></li><li>affixation: 接辞添加</li><li>OOV: Out of Vocabulary</li></ul><p>character copyingは人名などの固有名詞を翻訳せずそのままコピーする事らしい。</p><h2 id="対応したい事" tabindex="-1"><a class="header-anchor" href="#対応したい事"><span>対応したい事</span></a></h2><p>優秀な人間の翻訳家がはじめて接した単語でも翻訳が容易なケースが結構あり、これをNMTでも出来るようにする方法を考えたい。 以下のようなものはまぁまぁそのまま翻訳出来るという観察がある。</p><ul><li>固有名詞だがアルファベットが変わる、みたいなケース（Barck Obamaをバラク-オバマと翻訳する、みたいな）</li><li>同根語や借用語（claustrophobiaがドイツ語だとKlaustrophobieになる、とか）</li><li>複雑な形態素で構成された複合語や接辞添加された語など</li></ul><p>これらは、未知の単語をsubwordに分割して学習すればNMTがルールを学習出来て、未知の単語への対応力が増すのではないか？というのが仮説。</p><p>また、NMTは語彙サイズとテキストサイズの両方が重要だが両者はトレードオフがあるので、この辺もいい感じにしたい。 語彙サイズを増やしすぎないためにたまにしか出ないrare wordをどうにかしたいというモチベーション。</p><h2 id="byte-pair-encoding" tabindex="-1"><a class="header-anchor" href="#byte-pair-encoding"><span>Byte Pair Encoding</span></a></h2><p>二つの文字が頻出するペアの時には別のバイトを割り当ててそれを使う、という感じ。 例のコードは文字間に空白を開けたデータに対して適用してペアにしたら空白が除去される、というのを示している。 この例はどうなんだ？</p><p>基本的にはペアをカウントしていって、大きいペアを置き換える、をnum_mergesというパラメータの分だけ置き換える。</p><p>翻訳元と翻訳先を別々にBPEを求める方法と、両方を混ぜて一つのBPEを学習する方法（joint BPEと呼んでいる）を検討していて、 前者の方がvocabは小さくなるが、後者の方が分割に一貫性があるので対応を学習しやすいかも、と言っていて、 英語-ロシア語の翻訳の時にはキリル文字をラテン文字に音訳してBPEを学習したあとにそのBPEを音訳してロシア語の方のBPEを処理した、とか書いてある。</p><h2 id="実験" tabindex="-1"><a class="header-anchor" href="#実験"><span>実験</span></a></h2><p>実証的に試したいのは以下との事。</p><ul><li>rare wordや未知語に対しての翻訳を改善出来るか？</li><li>サブワードへの分割手法ごとに、vocab size, text size, 翻訳品質 の良し悪しを比較</li></ul><p>WMT 2015の 英語ー＞ドイツ語(420万センテンス） と 英語ー＞ロシア語（260万センテンス） らしい。</p><p>Unigram F1というのは、翻訳結果に出て来る単語がどのくらい解答文の単語と一致しているかを測る指標らしい。へー。</p><h2 id="c2-50k-bigram" tabindex="-1"><a class="header-anchor" href="#c2-50k-bigram"><span>C2-50k bigram</span></a></h2><p>BPE以外の分割手法として翻訳まで評価しているのはバイグラムのみ。 バイグラムはシーケンス長(トークン数)が長くなってしまうので、 頻出50kの単語(short list)は分割しない、というワークアラウンドを入れている。</p><p>この場合shortlistに入っているがvocabに入っていない単語はどうなるんだろう？UNKが振られるのかな？ Table 1ではUnkは34になっているので違うか。 bigramの数は2万程度なのにshort list 5万を足すと6万9000になっているのだから、 vocabに足すのか。</p><h2 id="分割手法の善し悪しはどうだろう" tabindex="-1"><a class="header-anchor" href="#分割手法の善し悪しはどうだろう"><span>分割手法の善し悪しはどうだろう？</span></a></h2><p>バイグラムとBPEで翻訳品質を見ると、バイグラムの方がいいような…</p><p>shortlistの単語は一切学習できてないと思うと、なんかBPEのスコアも微妙だなぁ。</p><h2 id="コード読み" tabindex="-1"><a class="header-anchor" href="#コード読み"><span>コード読み</span></a></h2><p>BPE関連のコードは公開もされているのでコードも読む（<a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>でもコードの解説がそれなりにある）</p><h3 id="bpeのtoy-演習問題2-7" tabindex="-1"><a class="header-anchor" href="#bpeのtoy-演習問題2-7"><span>BPEのtoy(演習問題2.7)</span></a></h3><p><a href="https://colab.research.google.com/drive/1F44GzumRxwYAjYkV5-LpMeEsvBYarCYY?usp=sharing" target="_blank" rel="noopener noreferrer">Colab: toy_bpe.ipynb</a></p><p>vocabは空白が除去されたものになっている。これはもともとコーパスに空白区切りのこれらの単語が5回、2回、6回、3回あたえられた時にBPEを実行していくとどうなるか、という話だと思う。</p><p>何を理解してもらおうとしているかは正直良く分からない。</p><p>途中でestなどがサブワードとして扱われるのは正しそうにも見えるが、lowはサブワードとしてはなかなか使われない。それは<code>w@</code> (＜/w＞はこのWikiと相性悪いので単語の終わりはアットマークで代用)が一つとみなされてしまって、lowerのlowと同じに見えないから。 ただloは割と早い段階でサブワードと認識される。</p><p><code>est@</code>がloよりも先にサブワードとして認識されるのはこのBPEのアルゴリズムの動きを理解する助けにはなる気がする。（BPEのBPEを置き換えるので二文字では無く3文字が置き換え対象になるメカニズム）。</p><p>あと単語の頻度に大きく依存するのもこのアルゴリズムからは予想出来る。</p><h3 id="learn-bpeのコード" tabindex="-1"><a class="header-anchor" href="#learn-bpeのコード"><span>learn_bpeのコード</span></a></h3><p>抜粋しているコードは良く意味が分からないのでいろいろ見ていったが、結局最初から見ていく必要がありそう。</p><p>まずvocabが何か？を見ていみると、まずはvocabは単語をキーにして頻度をvalueとした辞書を作っている。 単純にファイルを開いて空白でsplitしていて、ファイルの方には文章のテキストが入っている（全部小文字っぽい）。</p><p>例えば以下か。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line">vocab <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token string">&quot;the&quot;</span><span class="token punctuation">:</span> <span class="token number">10</span><span class="token punctuation">,</span> <span class="token string">&quot;a&quot;</span><span class="token punctuation">:</span> <span class="token number">23</span><span class="token punctuation">,</span> <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>その後にこれを以下のように変更している。(is_byteは消してcharの方だけ残してる）</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line">    vocab <span class="token operator">=</span> get_vocabulary<span class="token punctuation">(</span>infile<span class="token punctuation">,</span> is_dict<span class="token punctuation">,</span> is_bytes<span class="token punctuation">,</span> num_workers<span class="token punctuation">)</span></span>
<span class="line">    vocab <span class="token operator">=</span> <span class="token builtin">dict</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">(</span><span class="token builtin">tuple</span><span class="token punctuation">(</span>x<span class="token punctuation">[</span><span class="token punctuation">:</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">+</span><span class="token punctuation">(</span>x<span class="token punctuation">[</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token operator">+</span><span class="token string">&#39;&lt;/w&gt;&#39;</span><span class="token punctuation">,</span><span class="token punctuation">)</span> <span class="token punctuation">,</span>y<span class="token punctuation">)</span> <span class="token keyword">for</span> <span class="token punctuation">(</span>x<span class="token punctuation">,</span>y<span class="token punctuation">)</span> <span class="token keyword">in</span> vocab<span class="token punctuation">.</span>items<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line">    sorted_vocab <span class="token operator">=</span> <span class="token builtin">sorted</span><span class="token punctuation">(</span>vocab<span class="token punctuation">.</span>items<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> key<span class="token operator">=</span><span class="token keyword">lambda</span> x<span class="token punctuation">:</span> x<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">,</span> reverse<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>vocabはキーが</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token punctuation">(</span><span class="token string">&#39;t&#39;</span> <span class="token string">&#39;h&#39;</span> <span class="token string">&#39;e@&#39;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>のタプルで、値は頻度のまま、となるか。 これがtoy_bpeと違うのが酷いなぁ。</p><p>ちなみに関数の引数側でvocabと呼んでいるものはだいたいsorted_vocab。</p><p>次にindices。これは以下でstatsを一緒に作っている。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">def</span> <span class="token function">get_pair_statistics</span><span class="token punctuation">(</span>vocab<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token triple-quoted-string string">&quot;&quot;&quot;Count frequency of all symbol pairs, and create index&quot;&quot;&quot;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment"># data structure of pair frequencies</span></span>
<span class="line">    stats <span class="token operator">=</span> defaultdict<span class="token punctuation">(</span><span class="token builtin">int</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">#index from pairs to words</span></span>
<span class="line">    indices <span class="token operator">=</span> defaultdict<span class="token punctuation">(</span><span class="token keyword">lambda</span><span class="token punctuation">:</span> defaultdict<span class="token punctuation">(</span><span class="token builtin">int</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> i<span class="token punctuation">,</span> <span class="token punctuation">(</span>word<span class="token punctuation">,</span> freq<span class="token punctuation">)</span> <span class="token keyword">in</span> <span class="token builtin">enumerate</span><span class="token punctuation">(</span>vocab<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">        prev_char <span class="token operator">=</span> word<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span></span>
<span class="line">        <span class="token keyword">for</span> char <span class="token keyword">in</span> word<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">:</span><span class="token punctuation">]</span><span class="token punctuation">:</span></span>
<span class="line">            stats<span class="token punctuation">[</span>prev_char<span class="token punctuation">,</span> char<span class="token punctuation">]</span> <span class="token operator">+=</span> freq</span>
<span class="line">            indices<span class="token punctuation">[</span>prev_char<span class="token punctuation">,</span> char<span class="token punctuation">]</span><span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">+=</span> <span class="token number">1</span></span>
<span class="line">            prev_char <span class="token operator">=</span> char</span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> stats<span class="token punctuation">,</span> indices</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>indices[pair]</code>でdictが返り、そのキーはそのbpeが登場したwordを表すsorted_vocabのindex。valueはそのword内に幾つ入っていたか。 結構ややこしいがだいたい分かった。</p><p>ちなみにstatsはペアのfreq。</p><p>次に本を読んでいて良くわからなかったのがbig_statsとstatsの関係。 なんかstatsが同じに見えるような？</p><p>と元コードを見るとforの最後が以下だ。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line">        changes <span class="token operator">=</span> replace_pair<span class="token punctuation">(</span>most_frequent<span class="token punctuation">,</span> sorted_vocab<span class="token punctuation">,</span> indices<span class="token punctuation">,</span> is_bytes<span class="token punctuation">)</span></span>
<span class="line">        update_pair_statistics<span class="token punctuation">(</span>most_frequent<span class="token punctuation">,</span> changes<span class="token punctuation">,</span> stats<span class="token punctuation">,</span> indices<span class="token punctuation">)</span></span>
<span class="line">        stats<span class="token punctuation">[</span>most_frequent<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token number">0</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token keyword">not</span> i <span class="token operator">%</span> <span class="token number">100</span><span class="token punctuation">:</span></span>
<span class="line">            prune_stats<span class="token punctuation">(</span>stats<span class="token punctuation">,</span> big_stats<span class="token punctuation">,</span> threshold<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>いやいや、ここ無いと分からんでしょ！？と思ってしまうが。0を入れる事でmost_frequentは取り除いている訳だな。</p><p>replace_pairは以下みたいな感じ（多少改変している）</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line">    iterator <span class="token operator">=</span> indices<span class="token punctuation">[</span>pair<span class="token punctuation">]</span><span class="token punctuation">.</span>items<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">for</span> j<span class="token punctuation">,</span> freq <span class="token keyword">in</span> iterator<span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">if</span> freq <span class="token operator">&lt;</span> <span class="token number">1</span><span class="token punctuation">:</span></span>
<span class="line">            <span class="token keyword">continue</span></span>
<span class="line">        word<span class="token punctuation">,</span> freq <span class="token operator">=</span> vocab<span class="token punctuation">[</span>j<span class="token punctuation">]</span></span>
<span class="line">        new_word <span class="token operator">=</span> split_char<span class="token punctuation">.</span>join<span class="token punctuation">(</span>word<span class="token punctuation">)</span></span>
<span class="line">        new_word <span class="token operator">=</span> pattern<span class="token punctuation">.</span>sub<span class="token punctuation">(</span>pair_str<span class="token punctuation">,</span> new_word<span class="token punctuation">)</span></span>
<span class="line">        new_word <span class="token operator">=</span> <span class="token builtin">tuple</span><span class="token punctuation">(</span>new_word<span class="token punctuation">.</span>split<span class="token punctuation">(</span>split_char<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">        vocab<span class="token punctuation">[</span>j<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">(</span>new_word<span class="token punctuation">,</span> freq<span class="token punctuation">)</span></span>
<span class="line">        changes<span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token punctuation">(</span>j<span class="token punctuation">,</span> new_word<span class="token punctuation">,</span> word<span class="token punctuation">,</span> freq<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>new_wordはタプルをsplit_charでジョインしている。<code>t h e@</code>とかになる訳だな。 で、pair_strは例えば<code>he@</code>なら&#39;h e@&#39;とか空白でつなげたものになっていて、これを<code>he@</code>に置き換える。</p><p>そして最後にsplitするので、</p><p><code>(t, he@)</code> というタプルになる訳か。</p><p>vocabがまずは文字ごとのタプルになって、その後にbpeで置き換えられていくんだな。ややこしい。</p><p>update_pair_staticsをちらっと見ると、これは<code>he@</code>とマージしたら<code>(t, h)</code>のペアの頻度を下げたりしている。 当然<code>t, he@</code>の頻度はその分あげるのだろう。</p><p>prune_statsを見る。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">def</span> <span class="token function">prune_stats</span><span class="token punctuation">(</span>stats<span class="token punctuation">,</span> big_stats<span class="token punctuation">,</span> threshold<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token triple-quoted-string string">&quot;&quot;&quot;Prune statistics dict for efficiency of max()</span>
<span class="line"></span>
<span class="line">    The frequency of a symbol pair never increases, so pruning is generally safe</span>
<span class="line">    (until we the most frequent pair is less frequent than a pair we previously pruned)</span>
<span class="line">    big_stats keeps full statistics for when we need to access pruned items</span>
<span class="line">    &quot;&quot;&quot;</span></span>
<span class="line">    <span class="token keyword">for</span> item<span class="token punctuation">,</span>freq <span class="token keyword">in</span> <span class="token builtin">list</span><span class="token punctuation">(</span>stats<span class="token punctuation">.</span>items<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">if</span> freq <span class="token operator">&lt;</span> threshold<span class="token punctuation">:</span></span>
<span class="line">            <span class="token keyword">del</span> stats<span class="token punctuation">[</span>item<span class="token punctuation">]</span></span>
<span class="line">            <span class="token keyword">if</span> freq <span class="token operator">&lt;</span> <span class="token number">0</span><span class="token punctuation">:</span></span>
<span class="line">                big_stats<span class="token punctuation">[</span>item<span class="token punctuation">]</span> <span class="token operator">+=</span> freq</span>
<span class="line">            <span class="token keyword">else</span><span class="token punctuation">:</span></span>
<span class="line">                big_stats<span class="token punctuation">[</span>item<span class="token punctuation">]</span> <span class="token operator">=</span> freq</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>freqがthreshold以下のものをbig_statsに移すとはこういう感じか。</p><p>statsから低頻度のものを一時移して高頻度だけのものを残し、その中でbpeの統計をとったり置き換えたりの処理をしていく。 statsやbig_statsはあくまで調べるbpであってvocabなどはそのまま全体を見ている。</p><p>大きい頻度のものが全部処理されてしまったりマージ処理の分かれ具合でthresholdより下になってしまったら、そもそもにbig_statsの方にもっと大きいものがあるはずなので全体を取り直してまた再計算しましょう、という事かな。マージ処理で減少するケースが本当にあるかどうかはコード動かしてみないと自信が持てないが。</p><p>まぁだいたいは理解したか。いやぁ、これは本文の解説はいまいちだな。演習問題を答えるにはちゃんと元ソースを読む必要があるので読めって事なんだろうが。</p><h3 id="encode関数" tabindex="-1"><a class="header-anchor" href="#encode関数"><span>encode関数</span></a></h3><p><a href="https://colab.research.google.com/drive/1F44GzumRxwYAjYkV5-LpMeEsvBYarCYY?usp=sharing" target="_blank" rel="noopener noreferrer">Colab: bpe_toy.ipynb</a> に続きとして書く。</p><p>ちなみにサポートページの菊田さんの方が途中経過のprintがあってわかりやすい。</p><p><a href="https://colab.research.google.com/drive/1wom259xtR1ZPnD-ACYqegL98J5euagGm?usp=sharing#scrollTo=2fkROcD_Cc4I" target="_blank" rel="noopener noreferrer">原論文から解き明かす生成AI_演習問題2.9 - Colab</a></p>`,72)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};